def add_owner_members(apps, schema_editor):
    """Give every existing project its owner as the first human member.

    Only adds rows; Project fields, users and files are not touched.
    """
    Project = apps.get_model('projects', 'Project')
    ProjectMember = apps.get_model('projects', 'ProjectMember')
    existing = set(
        ProjectMember.objects.filter(user__isnull=False).values_list('project_id', 'user_id')
    )
    for project in Project.objects.select_related('owner').iterator():
        if (project.pk, project.owner_id) in existing:
            continue
        ProjectMember.objects.create(
            project_id=project.pk,
            kind='human',
            name=project.owner.username,
            role='项目负责人',
            user_id=project.owner_id,
        )


